import {createRenderer} from './renderer.js';
export function resetCamera(domain){return {schemaVersion:1,target:[0,0,0],yaw:.65,pitch:.32,distance:(domain.max[0]-domain.min[0])*1.55,fov:.68};}
export function makeState(){return {latestRequest:0,camera:resetCamera({min:[-1.5,-1.5,-1.5],max:[1.5,1.5,1.5]}),domain:null,recipe:null,generation:null};}
export function acceptResponse(state,response){if(response.requestId!==state.latestRequest)return false;state.generation=response;return true;}
export function validCamera(c){return c&&c.schemaVersion===1&&Array.isArray(c.target)&&c.target.length===3&&c.target.every(v=>Number.isFinite(v)&&Math.abs(v)<=100)&&['yaw','pitch','distance','fov'].every(k=>Number.isFinite(c[k]))&&Math.abs(c.pitch)<1.5&&c.distance>.05&&c.distance<100&&c.fov>.1&&c.fov<2;}
function validRecipe(r){
 if(r?.schemaVersion===3)return validHeightfieldRecipe(r);
 const supported=r&&((r.schemaVersion===1&&r.generatorVersion==='rocks-v2')||(r.schemaVersion===2&&((r.generatorVersion==='rocks-v3'&&['fractured_wall','irregular_beds','overhang'].includes(r.family))||(['rocks-v4','rocks-v5','rocks-v6'].includes(r.generatorVersion)&&['common_rock','cliff','strata'].includes(r.family))||(r.generatorVersion==='rocks-v7'&&r.family==='weathered_boulder')||(r.generatorVersion==='rocks-v8'&&r.family==='cliff_plateau')||(r.generatorVersion==='rocks-v12'&&['columnar_basalt','jointed_granite'].includes(r.family)))));
 if(!supported)return false;
 if(r.generatorVersion==='rocks-v12'){
  const keys=['schemaVersion','generatorVersion','extractorVersion','family','units','seed','size','layerThickness','contrast','wear','grid','studySpacing'].concat(Object.hasOwn(r,'detail')?['detail']:[]).concat(r.family==='columnar_basalt'?['columnCount','columnLean','jointDepth']:['roundness','chipping']);if(Object.keys(r).length!==keys.length||!keys.every(k=>Object.hasOwn(r,k))||!r.grid||Object.keys(r.grid).length!==1)return false;
  if(r.wear!==0||(r.detail??0)!==0||r.extractorVersion!==(r.family==='columnar_basalt'?'poly-csg-v1':'paris-mc-v1'))return false;
  const ranges=[['studySpacing',.3,.6]].concat(r.family==='columnar_basalt'?[['columnLean',-.15,.15],['jointDepth',0,1]]:[['roundness',.06,.2],['chipping',0,1]]);
  if(!ranges.every(([k,lo,hi])=>Number.isFinite(r[k])&&r[k]>=lo&&r[k]<=hi))return false;
  if(r.family==='columnar_basalt'&&(!Number.isInteger(r.columnCount)||r.columnCount<3||r.columnCount>7))return false;
 }

 if(r.generatorVersion==='rocks-v7'&&(r.extractorVersion!=='paris-mc-v1'||r.wear!==0))return false;
 if(['rocks-v6','rocks-v8'].includes(r.generatorVersion)&&r.extractorVersion!=='poly-csg-v1')return false;
 if(r.generatorVersion==='rocks-v8'&&(r.detail||0)!==0)return false;
 return (r.extractorVersion==='paris-mc-v1'||(r.schemaVersion===2&&r.extractorVersion==='poly-csg-v1'&&r.wear===0))&&r.units==='m'&&Number.isInteger(r.seed)&&r.seed>=0&&r.seed<=4294967295&&[64,128].includes(r.grid?.cells)&&['size','layerThickness','contrast','wear'].every(k=>Number.isFinite(r[k]))&&r.size>=.1&&r.size<=10&&(r.generatorVersion==='rocks-v12'?r.layerThickness>0:r.layerThickness>=(r.extractorVersion==='poly-csg-v1'?.02*r.size:6*r.size/r.grid.cells)&&r.layerThickness<=.7*r.size)&&r.contrast>=0&&r.contrast<=1&&r.wear>=0&&r.wear<=1&&(r.detail===undefined||(Number.isFinite(r.detail)&&r.detail>=0&&r.detail<=1));
}
const heightfieldKeys=['schemaVersion','generatorVersion','extractorVersion','family','units','seed','size','relief','backDepth','bedCount','thicknessVariation','tiltDegrees','fractures','irregularity','fragmentedContacts','grid'];
const jointedKeys=heightfieldKeys.filter(k=>!['bedCount','thicknessVariation','tiltDegrees','fragmentedContacts'].includes(k)).concat(['profile','directionDegrees','jointSpacing','jointDepth','blockScale']);
function validHeightfieldRecipe(r){
 const jointed=r.generatorVersion==='heightfield-cliff-v11',keys=jointed?jointedKeys:heightfieldKeys;
 if(Object.keys(r).length!==keys.length||!keys.every(k=>Object.hasOwn(r,k))||!['heightfield-cliff-v10','heightfield-cliff-v11'].includes(r.generatorVersion)||r.extractorVersion!=='heightfield-solid-v2'||r.family!=='heightfield_cliff'||r.units!=='m')return false;
 if(!Number.isInteger(r.seed)||r.seed<0||r.seed>4294967295)return false;
 if(jointed?!['massive_oblique','vertical_channels'].includes(r.profile):(!Number.isInteger(r.bedCount)||r.bedCount<4||r.bedCount>24||typeof r.fragmentedContacts!=='boolean'))return false;
 if(!r.grid||Object.keys(r.grid).length!==3||!['cells','width','height'].every(k=>Number.isInteger(r.grid[k])&&r.grid[k]>=2&&r.grid[k]<=(k==='cells'?256:4096)))return false;
 const ranges=[['size',.1,10],['relief',0,.5*r.size],['backDepth',.02*r.size,.5*r.size],['fractures',0,1],['irregularity',0,1]].concat(jointed?[['directionDegrees',-90,90],['jointSpacing',.08,.6],['jointDepth',0,1],['blockScale',.12,.6]]:[['thicknessVariation',0,1],['tiltDegrees',-45,45]]);
 return ranges.every(([k,low,high])=>Number.isFinite(r[k])&&r[k]>=low&&r[k]<=high);
}
export function heightfieldRecipe(source={}){if(source.schemaVersion===3)return {...source,grid:{...source.grid}};const size=source.size??2;return {schemaVersion:3,generatorVersion:'heightfield-cliff-v10',extractorVersion:'heightfield-solid-v2',family:'heightfield_cliff',units:'m',seed:source.seed??48,size,relief:.45*size,backDepth:.15*size,bedCount:12,thicknessVariation:1,tiltDegrees:3.148096099562,fractures:1,irregularity:1,fragmentedContacts:false,grid:{cells:128,width:512,height:512}};}
export function cliffProfileRecipe(source,profile){
 const base=heightfieldRecipe(source);
 if(profile==='stratified'){
  if(base.generatorVersion==='heightfield-cliff-v10')return base;
  const original=heightfieldRecipe({seed:base.seed,size:base.size});for(const k of ['relief','backDepth','fractures','irregularity','grid'])original[k]=base[k];return original;
 }
 if(base.generatorVersion==='heightfield-cliff-v11')return {...base,profile};
 for(const k of ['bedCount','thicknessVariation','tiltDegrees','fragmentedContacts'])delete base[k];
 return {...base,generatorVersion:'heightfield-cliff-v11',profile,directionDegrees:0,jointSpacing:.24,jointDepth:.65,blockScale:.28};
}
export function familyRecipe(source,family,detail){
 if(family==='heightfield_cliff')return heightfieldRecipe(source);
 const r=source?.schemaVersion===3?{schemaVersion:1,generatorVersion:'rocks-v2',extractorVersion:'paris-mc-v1',units:'m',seed:source.seed,size:source.size,layerThickness:.25*source.size,contrast:.75,wear:0,grid:{cells:128}}:{...source};
 const study=['columnar_basalt','jointed_granite'].includes(family),keep=study&&source?.family===family&&source?.generatorVersion==='rocks-v12';
 if(!keep)for(const key of ['studySpacing','columnCount','columnLean','jointDepth','roundness','chipping'])delete r[key];
 if(family==='stratified'){r.schemaVersion=1;r.generatorVersion='rocks-v2';r.extractorVersion='paris-mc-v1';delete r.family;delete r.detail;}
 else{r.schemaVersion=2;r.generatorVersion=study?'rocks-v12':family==='weathered_boulder'?'rocks-v7':family==='cliff_plateau'?'rocks-v8':['common_rock','cliff','strata'].includes(family)?'rocks-v5':'rocks-v3';r.extractorVersion=['weathered_boulder','jointed_granite'].includes(family)?'paris-mc-v1':'poly-csg-v1';r.family=family;r.wear=0;r.detail=study||family==='cliff_plateau'?0:detail;}
 if(study&&!keep)Object.assign(r,{studySpacing:.45},family==='columnar_basalt'?{columnCount:5,columnLean:.08,jointDepth:.4}:{roundness:.12,chipping:.35});
 return r;
}

const $=s=>document.querySelector(s);
async function start(){const state=makeState(),bootstrapEpoch=state.latestRequest,names=['base','stratified','eroded'];const renderers=names.map(n=>createRenderer($('#'+n)));let materials=[],editingProfile='stratified';const status=t=>$('#status').textContent=t;const cameras=(persist=true)=>{renderers.forEach(r=>r.setCamera(state.camera));if(persist)localStorage.setItem('rocks-camera',JSON.stringify(state.camera));};cameras(false);const save=(name,data)=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
 function setInputs(r,present=true){const hf=r.schemaVersion===3,study=r.generatorVersion==='rocks-v12',poly=r.extractorVersion==='poly-csg-v1';$('#legacyControls').hidden=hf||study;$('#igneousControls').hidden=!study;$('#basaltControls').hidden=!study||r.family!=='columnar_basalt';$('#graniteControls').hidden=!study||r.family!=='jointed_granite';if(study)for(const k of ['studySpacing','columnCount','columnLean','jointDepth','roundness','chipping'])if(r[k]!==undefined)$('#study-'+k).value=r[k];$('#heightfieldControls').hidden=!hf;$('#wear').disabled=poly||study||r.family==='weathered_boulder';$('#cells').disabled=poly;$('#cells').min=hf?2:64;$('#cells').max=hf?256:128;$('#cells').step=hf?1:64;$('#detail').disabled=r.schemaVersion!==2||r.family==='cliff_plateau';$('#detail').value=r.detail||0;$('#family').value=r.family||'stratified';for(let k of ['seed','size'])$('#'+k).value=r[k];$('#cells').value=r.grid.cells;
  if(hf){const jointed=r.generatorVersion==='heightfield-cliff-v11';editingProfile=r.profile||'stratified';$('#cliffProfile').value=editingProfile;$('#beddingControls').hidden=jointed;$('#jointControls').hidden=!jointed;for(let k of ['bedCount','thicknessVariation','tiltDegrees','relief','backDepth','fractures','irregularity','directionDegrees','jointSpacing','jointDepth','blockScale'])if(r[k]!==undefined)$('#'+k).value=r[k];$('#fragmentedContacts').checked=r.fragmentedContacts||false;$('#sampleWidth').value=r.grid.width;$('#sampleHeight').value=r.grid.height;}else{for(let k of ['layerThickness','contrast','wear'])$('#'+k).value=r[k];}
  if(!present)return;document.body.dataset.heightfield=String(hf);document.body.dataset.poly=String(poly);
  $('#resistanceOption').disabled=hf||study;if((hf||study)&&$('#mode').value==='resistance'){$('#mode').value='neutral';renderers.forEach(r=>r.setMode?.('neutral'));$('#legend').hidden=true;}
  $('#base-title').textContent=hf?'01 / RELIEVE PROCEDURAL':'01 / BASE';$('#base-description').textContent=hf?'Frente 2.5D · respaldo cerrado':study?'Envolvente 3D · antes de juntas':'Planos · masa continua';$('#routeNote').textContent=hf?'Alturas calculadas en C++. Sin píxeles de referencia ni salientes. El relieve escala Z; la textura solo aporta color.':study?'Volumen 3D matemático. Juntas y redondez geométricas; sin erosión simulada ni píxeles de referencia.':'Tres etapas geométricas; las texturas solo aportan color.';
 }
 function inputs(){const family=$('#family').value;let r=familyRecipe(state.recipe||{},family,Number($('#detail').value));r.seed=Number($('#seed').value);r.size=Number($('#size').value);r.grid={...r.grid,cells:Number($('#cells').value)};
  if(r.generatorVersion==='rocks-v12'){for(const k of ['studySpacing'].concat(family==='columnar_basalt'?['columnCount','columnLean','jointDepth']:['roundness','chipping']))r[k]=Number($('#study-'+k).value);r.wear=0;r.detail=0;}else if(family==='heightfield_cliff'){r=cliffProfileRecipe(r,$('#cliffProfile').value||'stratified');const jointed=r.generatorVersion==='heightfield-cliff-v11';for(let k of ['relief','backDepth','fractures','irregularity'].concat(jointed?['directionDegrees','jointSpacing','jointDepth','blockScale']:['bedCount','thicknessVariation','tiltDegrees']))r[k]=Number($('#'+k).value);if(!jointed)r.fragmentedContacts=$('#fragmentedContacts').checked;r.grid.width=Number($('#sampleWidth').value);r.grid.height=Number($('#sampleHeight').value);}else{for(let k of ['layerThickness','contrast','wear'])r[k]=Number($('#'+k).value);if(r.extractorVersion==='poly-csg-v1')r.wear=0;}return r;
 }
 async function load(response,recipe){if(response.requestId!==state.latestRequest)return;let t=performance.now(),raw=await(await fetch(response.viewerUrl)).text(),transfer=performance.now()-t;t=performance.now();let data=JSON.parse(raw),parse=performance.now()-t;let metrics=await(await fetch(response.metricsUrl)).json();if(!acceptResponse(state,response))return;state.recipe=recipe;state.domain=data.domain;setInputs(recipe);let upload=0;const activeNames=recipe.schemaVersion===3?['heightfield']:names;activeNames.forEach((n,i)=>{upload+=renderers[i].setMesh(data.stages[n]);let m=metrics.stages[n];$('#'+names[i]+'-stats').textContent=`${m.vertices.toLocaleString()} vértices · ${m.triangles.toLocaleString()} triángulos · V ${m.signedVolume.toFixed(4)} m³`;});cameras();localStorage.setItem('rocks-camera',JSON.stringify(state.camera));$('#downloads').replaceChildren(...activeNames.concat('recipe').map(n=>{let a=document.createElement('a');a.href=response.exports[n];a.download=n==='recipe'?'recipe.json':n+'.obj';a.textContent=n==='recipe'?'JSON':n+'.obj';return a}));let a=document.createElement('a');a.href=response.metricsUrl;a.textContent='Métricas';a.target='_blank';$('#downloads').append(a);status(`Aceptado · ${recipe.schemaVersion===3?`Heightfield ${recipe.grid.cells}² · rango fijo · recortes ${(metrics.clippedLow||0)+(metrics.clippedHigh||0)}`:recipe.extractorVersion==='poly-csg-v1'?'CSG planar · sin desgaste curvo':recipe.grid.cells+'³'} · seed ${recipe.seed} · cerrado / manifold / 1 componente. Transferencia ${transfer.toFixed(0)} ms · parseo ${parse.toFixed(0)} ms · CPU malla/upload ${upload.toFixed(0)} ms`);document.body.dataset.ready='true';window.labEvidence={transferMs:transfer,parseMs:parse,bufferUploadMs:upload,camera:state.camera,recipe,metrics};}
 async function generate(recipe){if(!validRecipe(recipe))throw Error('Receta inválida: revisa los rangos de la ruta seleccionada.');let requestId=++state.latestRequest;status('Generando y validando en C++…');$('#generate').disabled=true;try{let response=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId,recipe})});let result=await response.json();if(!response.ok)throw Error(result.error);await load(result,recipe);}finally{if(requestId===state.latestRequest)$('#generate').disabled=false;}}
 const guarded=fn=>async e=>{try{await fn(e)}catch(err){status('Error: '+err.message);document.body.dataset.error=err.message}};
 $('#cliffProfile').onchange=()=>{const chosen=$('#cliffProfile').value;$('#cliffProfile').value=editingProfile;const before=inputs();setInputs(cliffProfileRecipe(before,chosen),false)};
 $('#family').onchange=()=>{const r=familyRecipe(state.recipe||heightfieldRecipe(),$('#family').value,Number($('#detail').value));setInputs(r,false)};$('#generate').onclick=guarded(()=>generate(inputs()));$('#mode').onchange=()=>{renderers.forEach(r=>r.setMode($('#mode').value));$('#legend').hidden=$('#mode').value!=='resistance'};
 $('#reset').onclick=()=>{state.camera=resetCamera(state.domain||{min:[-1.5,-1.5,-1.5],max:[1.5,1.5,1.5]});cameras()};document.querySelectorAll('[data-pose]').forEach(b=>b.onclick=()=>{let p=b.dataset.pose;state.camera.yaw=p==='front'?0:p==='side'?Math.PI/2:.65;state.camera.pitch=p==='three'?.32:0;cameras()});
 names.forEach(n=>{let canvas=$('#'+n),last;canvas.onpointerdown=e=>{last=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointerup=()=>{last=null;localStorage.setItem('rocks-camera',JSON.stringify(state.camera))};canvas.onpointermove=e=>{if(!last)return;state.camera.yaw-=(e.clientX-last[0])*.008;state.camera.pitch=Math.max(-1.4,Math.min(1.4,state.camera.pitch+(e.clientY-last[1])*.008));last=[e.clientX,e.clientY];cameras()};canvas.onwheel=e=>{e.preventDefault();state.camera.distance=Math.max(.2,Math.min(80,state.camera.distance*Math.exp(e.deltaY*.001)));cameras()}});
 window.addEventListener('resize',()=>renderers.forEach(r=>r.draw()));$('#exportRecipe').onclick=()=>save('recipe.json',state.recipe);$('#exportCamera').onclick=()=>save('camera.json',state.camera);$('#importRecipe').onchange=guarded(async e=>{let r=JSON.parse(await e.target.files[0].text());if(!validRecipe(r))throw Error('Receta importada inválida; resultado conservado.');await generate(r)});$('#importCamera').onchange=guarded(async e=>{let c=JSON.parse(await e.target.files[0].text());if(!validCamera(c))throw Error('Cámara inválida');state.camera=c;cameras()});
 $('#material').onchange=guarded(async()=>{let mat=materials.find(m=>m.id===$('#material').value);if(mat)await Promise.all(renderers.map(r=>r.setTexture('/'+mat.maps.baseColor.path)));});
 try{let manifest=await(await fetch('/assets/textures/polyhaven/manifest.json')).json();materials=manifest.materials;$('#material').replaceChildren(...materials.map(m=>{let o=document.createElement('option');o.value=m.id;o.textContent=m.name;return o}));await $('#material').onchange()}catch(e){status('Texturas opcionales: '+e.message)}
 let saved=localStorage.getItem('rocks-camera');if(saved){try{let c=JSON.parse(saved);if(validCamera(c))state.camera=c}catch{}}cameras(false);let current=await fetch('/api/current');if(state.latestRequest!==bootstrapEpoch)return;if(current.ok){let result=await current.json();if(state.latestRequest!==bootstrapEpoch)return;result={...result,requestId:++state.latestRequest};let recipe=await(await fetch(result.exports.recipe)).json();await load(result,recipe)}else{let defaultRecipe=await(await fetch('/default-recipe.json')).json();if(state.latestRequest!==bootstrapEpoch)return;state.recipe=defaultRecipe;setInputs(state.recipe);await generate(state.recipe)}
}
if(typeof document!=='undefined'&&document.querySelector('#panels'))start().catch(e=>{$('#status').textContent='Error: '+e.message;document.body.dataset.error=e.message;console.error(e)});
